retrieval.cypher:
MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)
WHERE EXISTS {
  (s)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'PI-405024'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

